    ('efb30fe0-8902-4bd2-b1c8-5e4d065be970', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'SCI') AND code = 'C2' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'easy' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'create' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Ánh sáng truyền theo đường thẳng. Theo em, nhận định trên đúng hay sai?', 'Anh sang truyen theo duong thang. Theo em, nhan dinh tren dung hay sai?', 'Ánh sáng truyền theo đường thẳng.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Khoa học','Lớp 4']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('fb8c1c25-ac7a-4354-bc01-05b00535c6f2', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'SCI') AND code = 'C3' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'remember' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Đâu là nhận định đúng?', 'Dau la nhan dinh dung?', 'Nhiệt có thể truyền từ vật nóng sang vật lạnh hơn.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Khoa học','Lớp 4']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('445a9aa9-93f7-4d6a-b521-7e9e0527a67b', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'SCI') AND code = 'C4' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'understand' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Động vật cần thức ăn, nước uống và không khí để sống và phát triển. Câu trên đúng hay sai?', 'Dong vat can thuc an, nuoc uong va khong khi de song va phat trien. Cau tren dung hay sai?', 'Động vật cần thức ăn, nước uống và không khí để sống và phát triển.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Khoa học','Lớp 4']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('6fcb62a8-1921-46a3-9623-b28896535cdf', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'SCI') AND code = 'C1' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'essay' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'apply' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Em hãy nêu 3 cách bảo vệ môi trường mà em có thể thực hiện hằng ngày.', 'Em hay neu 3 cach bao ve moi truong ma em co the thuc hien hang ngay.', 'Câu hỏi tự luận — chấm theo rubric của giáo viên.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Khoa học','Lớp 4']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('5fa8eb5e-5b1d-41b4-a020-eed41dd7692d', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'SCI') AND code = 'C2' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'analyze' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Rừng là nguồn tài nguyên quan trọng cần được bảo vệ và trồng mới. Theo em, nhận định trên đúng hay sai?', 'Rung la nguon tai nguyen quan trong can duoc bao ve va trong moi. Theo em, nhan dinh tren dung hay sai?', 'Rừng là nguồn tài nguyên quan trọng cần được bảo vệ và trồng mới.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Khoa học','Lớp 4']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('9788d774-99f5-4158-a6c0-007de01163b9', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'SCI') AND code = 'C3' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'evaluate' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Phương án nào dưới đây là đúng?', 'Phuong an nao duoi day la dung?', 'Rác thải cần được phân loại để bảo vệ môi trường.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Khoa học','Lớp 4']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('737119b1-9e95-4fd8-8c87-06d07c649b57', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'SCI') AND code = 'C4' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'create' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Chuỗi thức ăn không có mối liên hệ gì giữa các sinh vật. Câu trên đúng hay sai?', 'Chuoi thuc an khong co moi lien he gi giua cac sinh vat. Cau tren dung hay sai?', 'Chuỗi thức ăn thể hiện mối quan hệ ăn - bị ăn giữa các sinh vật.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Khoa học','Lớp 4']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('0e713c50-1505-4a7e-b66e-c9eb3020a129', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'SCI') AND code = 'C1' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'remember' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Ý nào sau đây phản ánh đúng nội dung đã học?', 'Y nao sau day phan anh dung noi dung da hoc?', 'Vệ sinh an toàn thực phẩm giúp phòng tránh ngộ độc.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Khoa học','Lớp 4']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('6d64b2ca-e5e3-4777-930c-31511de967a8', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'SCI') AND code = 'C2' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'understand' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Nước tồn tại ở 3 thể: rắn, lỏng, khí. Theo em, nhận định trên đúng hay sai?', 'Nuoc ton tai o 3 the: ran, long, khi. Theo em, nhan dinh tren dung hay sai?', 'Nước tồn tại ở 3 thể: rắn, lỏng, khí.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Khoa học','Lớp 4']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
