    ('f0072577-7a62-40ae-8697-ccf2371f227f', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'SCI') AND code = 'C2' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'easy' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'understand' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Âm thanh được tạo ra do sự rung động của vật. Theo em, nhận định trên đúng hay sai?', 'Am thanh duoc tao ra do su rung dong cua vat. Theo em, nhan dinh tren dung hay sai?', 'Âm thanh được tạo ra do sự rung động của vật.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Khoa học','Lớp 4']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
