    ('6cd355ca-dd6e-4264-8264-c36dffa18344', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'SCI') AND code = 'C4' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'analyze' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Cơ thể người cần đủ 4 nhóm chất dinh dưỡng: đạm, đường, béo, vitamin và khoáng chất. Câu trên đúng hay sai?', 'Co the nguoi can du 4 nhom chat dinh duong: dam, duong, beo, vitamin va khoang chat. Cau tren dung hay sai?', 'Cơ thể người cần đủ 4 nhóm chất dinh dưỡng: đạm, đường, béo, vitamin và khoáng chất.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Khoa học','Lớp 4']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
