    ('c022eaa9-c3c3-4193-b4d2-da0ad4adffa3', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 4 AND code = 'SCI') AND code = 'C4' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'easy' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'analyze' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Vệ sinh an toàn thực phẩm giúp phòng tránh ngộ độc. Câu trên đúng hay sai?', 'Ve sinh an toan thuc pham giup phong tranh ngo doc. Cau tren dung hay sai?', 'Vệ sinh an toàn thực phẩm giúp phòng tránh ngộ độc.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Khoa học','Lớp 4']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
